    { "sigla": "IE", "irregolari": 5460, "anno": 2025, "ordinati": 6260, "rimpatriati": 2030, "tasso": 32.4, "obiettivo_tasso": 60, "fonte": "https://ec.europa.eu/eurostat/databrowser/view/migr_eirtn/default/table" }
