  "vincoli": [
    { "nome": "Non-refoulement, senza eccezioni", "nome_en": "Non-refoulement, no exceptions", "nome_de": "Non-Refoulement, ohne Ausnahme", "testo": "Art. 3 CEDU (Soering, Chahal, Saadi c. Italia), art. 19 Carta UE, art. 33 Convenzione di Ginevra: nessuno può essere rinviato verso tortura o trattamenti inumani, nemmeno un terrorista. Il piano non lo aggira: chi non è rinviabile resta trattenuto o sorvegliato.", "testo_en": "Article 3 ECHR (Soering, Chahal, Saadi v Italy), Article 19 EU Charter, Article 33 Geneva Convention: nobody may be sent to torture or inhuman treatment, not even a terrorist. The plan does not get around it: those who cannot be returned stay detained or under surveillance.", "testo_de": "Art. 3 EMRK (Soering, Chahal, Saadi gegen Italien), Art. 19 EU-Charta, Art. 33 Genfer Konvention: niemand darf in Folter oder unmenschliche Behandlung zurückgeschickt werden, auch kein Terrorist. Der Plan umgeht das nicht: wer nicht rückführbar ist, bleibt in Haft oder unter Aufsicht.", "fonte": "https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=OJ:L_202602280" },
    { "nome": "Vita familiare (art. 8 CEDU): valutazione individuale", "nome_en": "Family life (Article 8 ECHR): individual assessment", "nome_de": "Familienleben (Art. 8 EMRK): Einzelfallprüfung", "testo": "Criteri Boultif/Üner/Maslov: gravità del reato, durata del soggiorno, legami familiari, interesse dei minori. Savran c. Danimarca (2021) ha imposto l'esame completo della proporzionalità; nel 2024 la Corte ha avallato le espulsioni danesi che lo fanno. L'espulsione automatica senza giudice non regge.", "testo_en": "Boultif/Üner/Maslov criteria: seriousness of the offence, length of stay, family ties, the children's interests. Savran v Denmark (2021) required a full proportionality review; in 2024 the Court upheld Danish expulsions that carry it out. Automatic expulsion without a judge does not hold.", "testo_de": "Boultif/Üner/Maslov-Kriterien: Schwere der Tat, Aufenthaltsdauer, Familienbindungen, Kindeswohl. Savran gegen Dänemark (2021) verlangte die volle Verhältnismäßigkeitsprüfung; 2024 bestätigte der Gerichtshof dänische Ausweisungen, die sie vornehmen. Automatische Ausweisung ohne Richter hält nicht.", "fonte": "https://www.echr.coe.int/documents/d/echr/cp_denmark_eng" },
    { "nome": "Trattenimento solo se il rimpatrio è in corso", "nome_en": "Detention only while removal is under way", "nome_de": "Haft nur bei laufender Abschiebung", "testo": "Art. 5 CEDU e art. 6 Carta (Kadzoev, Mahdi): il trattenimento è lecito solo con una prospettiva ragionevole di allontanamento e con diligenza; 24 mesi senza un paese che accetti il volo sono illegittimi.", "testo_en": "Article 5 ECHR and Article 6 Charter (Kadzoev, Mahdi): detention is lawful only with a reasonable prospect of removal pursued with diligence; 24 months without a country accepting the flight are unlawful.", "testo_de": "Art. 5 EMRK und Art. 6 Charta (Kadzoev, Mahdi): Haft ist nur bei realistischer Abschiebungsaussicht und zügigem Betreiben zulässig; 24 Monate ohne ein Land, das den Flug annimmt, sind rechtswidrig.", "fonte": "https://www.ejiltalk.org/the-new-eu-return-regulation-a-step-towards-crimmigration/" },
    { "nome": "Residenti legali: minaccia reale, attuale e grave", "nome_en": "Legal residents: real, present and serious threat", "nome_de": "Legal Aufhältige: tatsächliche, gegenwärtige und erhebliche Gefahr", "testo": "Lungo soggiornanti (dir. 2003/109, López Pastuzano), ricongiunti (dir. 2003/86) e rifugiati (C-8/22, C-402/22): la condanna da sola non basta, serve una valutazione della pericolosità attuale. Il piano accelera il riesame, non lo elimina.", "testo_en": "Long-term residents (Directive 2003/109, López Pastuzano), reunified family members (Directive 2003/86) and refugees (C-8/22, C-402/22): a conviction alone is not enough, an assessment of present dangerousness is required. The plan speeds up the review, it does not remove it.", "testo_de": "Daueraufenthaltsberechtigte (RL 2003/109, López Pastuzano), Nachgezogene (RL 2003/86) und Flüchtlinge (C-8/22, C-402/22): die Verurteilung allein genügt nicht, nötig ist die Prüfung der gegenwärtigen Gefährlichkeit. Der Plan beschleunigt die Überprüfung, schafft sie nicht ab.", "fonte": "https://curia.europa.eu/jcms/upload/docs/application/pdf/2023-07/cp230115en.pdf" },
    { "nome": "Ricorso effettivo (art. 13 CEDU, art. 47 Carta)", "nome_en": "Effective remedy (Article 13 ECHR, Article 47 Charter)", "nome_de": "Wirksamer Rechtsbehelf (Art. 13 EMRK, Art. 47 Charta)", "testo": "Se c'è un rischio di tortura il ricorso deve sospendere automaticamente il rimpatrio (Gebremedhin, Gnandi). Per tutti gli altri casi il regolamento toglie l'effetto sospensivo automatico: 14 giorni e un giudice che decide sulla sospensione.", "testo_en": "Where there is a risk of torture the appeal must automatically suspend the return (Gebremedhin, Gnandi). For all other cases the Regulation removes automatic suspensive effect: 14 days and a judge ruling on suspension.", "testo_de": "Bei Folterrisiko muss das Rechtsmittel die Rückführung automatisch aufschieben (Gebremedhin, Gnandi). In allen anderen Fällen nimmt die Verordnung die automatische aufschiebende Wirkung: 14 Tage und ein Richter entscheidet über die Aussetzung.", "fonte": "https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=OJ:L_202602280" },
    { "nome": "Paesi sicuri sotto controllo del giudice", "nome_en": "Safe countries under judicial review", "nome_de": "Sichere Staaten unter richterlicher Kontrolle", "testo": "Corte di giustizia, Alace e Canpelli (1 agosto 2025): la designazione per legge è ammessa solo se il giudice può verificarne i criteri con fonti accessibili; un paese non è sicuro se non protegge tutta la popolazione.", "testo_en": "Court of Justice, Alace and Canpelli (1 August 2025): designation by law is allowed only if the judge can verify the criteria from accessible sources; a country is not safe if it does not protect its whole population.", "testo_de": "EuGH, Alace und Canpelli (1. August 2025): die gesetzliche Einstufung ist nur zulässig, wenn der Richter die Kriterien anhand zugänglicher Quellen prüfen kann; ein Land ist nicht sicher, wenn es nicht die gesamte Bevölkerung schützt.", "fonte": "https://curia.europa.eu/jcms/jcms/p1_5071954/en" },
    { "nome": "Hub e centri esterni: la CEDU viaggia con lo Stato", "nome_en": "Hubs and external centres: the ECHR travels with the state", "nome_de": "Hubs und externe Zentren: die EMRK reist mit dem Staat", "testo": "Dove lo Stato membro controlla di fatto il centro (Italia-Albania) si applicano per intero artt. 3, 5, 8 e 13 CEDU; i trasferimenti verso gli hub richiedono decisioni individuali motivate (art. 4 Prot. 4: niente espulsioni collettive) e un monitoraggio indipendente. Minori non accompagnati esclusi.", "testo_en": "Where the member state effectively controls the centre (Italy-Albania) Articles 3, 5, 8 and 13 ECHR apply in full; transfers to hubs require reasoned individual decisions (Article 4 Protocol 4: no collective expulsions) and independent monitoring. Unaccompanied minors excluded.", "testo_de": "Wo der Mitgliedstaat das Zentrum faktisch kontrolliert (Italien-Albanien), gelten Art. 3, 5, 8 und 13 EMRK vollständig; Überstellungen in Hubs erfordern begründete Einzelentscheidungen (Art. 4 Prot. 4: keine Kollektivausweisungen) und unabhängige Überwachung. Unbegleitete Minderjährige ausgeschlossen.", "fonte": "https://eumigrlab.unimi.it/return-detention-centres-in-albania/" }
  ],
